/**
 * CARDÁPIO DO KENKO
 * Itens e preços conforme o cardápio de delivery. Ajustes de preço e
 * disponibilidade são feitos no painel /admin (`menuOverrides` no Firestore).
 */

export type Kind =
  | 'nigiri' | 'sashimi' | 'uramaki' | 'hot' | 'temaki' | 'combo'
  | 'gyoza' | 'noodle' | 'tempura' | 'skewer' | 'soup' | 'salad'
  | 'edamame' | 'dessert' | 'drink'

export type Tag = 'picante' | 'vegetariano' | 'chef' | 'novo' | 'frito' | 'cru'

export interface Addon { id: string; name: string; price: number }

export interface Category {
  id: string
  name: string
  jp: string
  kanji: string
  blurb: string
  addons?: Addon[]
}

export interface Product {
  id: string
  cat: string
  name: string
  jp?: string
  /** Subcategoria (categoria original do cardápio). Aparece como subtítulo quando a lista está aberta. */
  group?: string
  desc: string
  price: number
  pieces?: string
  kind: Kind
  tint: string
  /** Recorte de foto (ver src/data/photos.json). Se vazio, escolhe pelo tipo. */
  photo?: string
  tags?: Tag[]
  featured?: boolean
}

